const allowedOrigins = [
  "https://roamresearch.com",
  "http://localhost:3000",
  "app://obsidian.md",
];

const isVercelPreviewUrl = (origin: string): boolean =>
  /^https:\/\/.*-discourse-graph-[a-z0-9]+\.vercel\.app$/.test(origin);

