    const { code, message, name } = error;
    const status = code === "invalid space" ? 400 : 500;
    return Response.json(
      { code, message, name },
      {
        status,
        headers: myCorsHeaders,
      },
    );
  }

  return Response.json(data, { headers: myCorsHeaders });
});

